#!/bin/bash
set -e
echo "================================================================"
echo "================================================================"
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-start xnn-auto.sh"
LOCK_FILE="/var/lock/xnn-auto.lock"

# 定义日志函数（方便后续使用）
log() {
    echo "[$(date '+%Y-%m-%d %H:%M:%S')]-$*"
}

# 定义错误处理函数
error_handler() {
    log "脚本在第 $1 行出错，退出"
    exit 1
}

# 使用 flock 获取锁，-n 表示非阻塞（如果锁被占用则立即退出）
exec 279>"$LOCK_FILE"
if ! flock -n 279; then
    echo "[$(date '+%Y-%m-%d %H:%M:%S')]-错误：脚本已在运行，本次执行退出" >&2
    exit 1
fi

MAIN_DIR="${1:-/root}"

trap 'error_handler $LINENO' ERR

mkdir -p $MAIN_DIR/Dress
cd $MAIN_DIR/Dress
if git rev-parse --git-dir >/dev/null 2>&1; then
    git pull
else
    cd $MAIN_DIR
    rm -rf $MAIN_DIR/Dress
    git clone https://githubproxy.cc/https://github.com/cute-Dress/Dress.git
fi
rm -rf "$MAIN_DIR/xnn-index/"
# 创建目标目录
mkdir -p "$MAIN_DIR/xnn-index/xnn-image"
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-start image copy"
count=0
# 使用 find 查找图片/视频等，-iname 忽略大小写
find "$MAIN_DIR/Dress" -type f \( -iname "*.jpg" -o -iname "*.jpeg" -o -iname "*.png" \) -print0 | while IFS= read -r -d '' file; do
    # 提取扩展名（保留最后一个点后的部分）
    ext="${file##*.}"
    # 复制并重命名
    cp "$file" "$MAIN_DIR/xnn-index/xnn-image/$count.$ext"
    echo "[$(date '+%Y-%m-%d %H:%M:%S')]-$count : copy $file to $MAIN_DIR/xnn-index/xnn-image/$count.$ext"
    count=$((count + 1))
done
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-image copy done"
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-start create web file"
ls -1v $MAIN_DIR/xnn-index/xnn-image/ > $MAIN_DIR/xnn-index/index.txt
sed 's/^/.\/xnn-image\//' $MAIN_DIR/xnn-index/index.txt > $MAIN_DIR/xnn-index/xnn-image-index.txt
# 使用 awk 按行合并
awk 'NR==FNR {url[NR]=$0; next} {print "        <li><p><a href=\"" url[FNR] "\">" $0 "</a></p></li>"}' $MAIN_DIR/xnn-index/xnn-image-index.txt $MAIN_DIR/xnn-index/index.txt > $MAIN_DIR/xnn-index/ul.txt

# 生成 HTML 文件

cat > $MAIN_DIR/xnn-index/index.html <<EOF
<!DOCTYPE html>

<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta http-equiv="X-UA-Compatible" content="IE=edge">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="icon" href="favicon.png">
        <link rel="stylesheet" href="info.css">
<title>可爱的小男娘</title>
</head>
<body>
    <h1>可爱的小男娘</h1>
EOF
echo "<h3>[$(date '+%Y-%m-%d %H:%M:%S')]-由自动化脚本构建</h3>" >> $MAIN_DIR/xnn-index/index.html
cat >> $MAIN_DIR/xnn-index/index.html <<EOF
    <p>可以点击超链接查看下面的照片，或者<a href="./xnn-image-index.txt">查看所有链接</a><br>源自<a href="https://github.com/cute-Dress/Dress">Dress项目</a></p>
    <ul style="line-height: 2px;">
EOF

cat $MAIN_DIR/xnn-index/ul.txt >> $MAIN_DIR/xnn-index/index.html

cat >> $MAIN_DIR/xnn-index/index.html <<EOF
    </ul>
</body>
</html>
EOF
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-create file done"
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-start create favicon"
cp $MAIN_DIR/xnn-index/index.html $MAIN_DIR/xnn-index/xnn-image-index.html
cat > $MAIN_DIR/xnn-index/favicon.hex <<'EOF'

EOF

xxd -r -p $MAIN_DIR/xnn-index/favicon.hex $MAIN_DIR/xnn-index/favicon.png
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-favicon create done"

echo "[$(date '+%Y-%m-%d %H:%M:%S')]-start delete build file"
#垃圾文件清理
rm -rf $MAIN_DIR/xnn-index/index.txt
rm -rf $MAIN_DIR/xnn-index/ul.txt
rm -f $MAIN_DIR/xnn-index/favicon.hex

echo "[$(date '+%Y-%m-%d %H:%M:%S')]-delete build file done"

echo "[$(date '+%Y-%m-%d %H:%M:%S')]-start upload to cloudflare pages"
#cloudflare pages 上传

# 部署到 Cloudflare Pages

# 检查是否已登录 wrangler
if ! wrangler whoami >/dev/null 2>&1; then
    echo "[$(date '+%Y-%m-%d %H:%M:%S')]-请先运行 wrangler login 进行身份验证"
    exit 1
fi

# 部署到 Cloudflare Workers Sites（需要先配置 wrangler.toml）
wrangler pages deploy $MAIN_DIR/xnn-index --project-name=xnn-image --branch=main
echo "[$(date '+%Y-%m-%d %H:%M:%S')]-done"